/// <reference types="vite/client" />
/**
 * The office as five movable rooms on a hallway (kit: assets/office-rooms.json,
 * generated by office/art/layout.py — compose() here is the twin of its compose()).
 *
 * Each room block carries its own walls, doors and furniture; the gaps between
 * blocks are hallway floor, so any arrangement stays walkable. Users move a room by
 * dragging its name plate and grow it by its corner handle (RoomOverlay); positions
 * and sizes are remembered per browser.
 */
import type { OfficeLayout } from '../office/types.js';

export interface RoomBlock {
  label: string;
  color: string;
  desc: string;
  w: number;
  h: number;
  tiles: number[];
  colors: Array<Record<string, number> | null>;
  furniture: Array<{ type: string; col: number; row: number }>;
  /** Top-left of the block in hallway tiles (row 0 of a block is its wall-item overhang). */
  x: number;
  y: number;
}

export interface RoomKit {
  hallway: { floor: number; color: Record<string, number> };
  gap: number;
  top: number;
  rooms: RoomBlock[];
  pets: Array<{ id: string; petType: number }>;
}

export const ROOM_EMOJI: Record<string, string> = {
  자료실: '📚',
  사무실: '🗂',
  상담실: '🔔',
  작업실: '🔧',
  휴게실: '☕',
};

const WALL = 0;
const VOID = 255;
const MAX_TILES = 64; // the office engine's MAX_COLS / MAX_ROWS
const POS_KEY = 'agenthub.office.roomPos';
const SIZE_KEY = 'agenthub.office.roomSize';
/** How far a room may grow past its designed size, in tiles. */
export const ROOM_MAX_GROW = 16;

let kit: RoomKit | null = null;
/** Each room as designed (the kit's own size) — resizing always starts from this. */
const designs = new Map<string, Pick<RoomBlock, 'w' | 'h' | 'tiles' | 'colors' | 'furniture'>>();

export function getKit(): RoomKit | null {
  return kit;
}

export async function loadKit(): Promise<RoomKit | null> {
  try {
    const r = await fetch(`${import.meta.env.BASE_URL}assets/office-rooms.json`);
    kit = (await r.json()) as RoomKit;
  } catch {
    kit = null;
    return null;
  }
  designs.clear();
  for (const room of kit.rooms) designs.set(room.label, { ...room });
  try {
    const sizes = JSON.parse(localStorage.getItem(SIZE_KEY) ?? '{}') as Record<string, { w: number; h: number }>;
    for (const room of kit.rooms) {
      const z = sizes[room.label];
      if (z) applySize(room, z.w, z.h);
    }
  } catch {
    /* no saved sizes — as designed */
  }
  try {
    const saved = JSON.parse(localStorage.getItem(POS_KEY) ?? '{}') as Record<string, { x: number; y: number }>;
    for (const room of kit.rooms) {
      const p = saved[room.label];
      if (p && canPlace(room.label, p.x, p.y)) {
        room.x = p.x;
        room.y = p.y;
      }
    }
  } catch {
    /* no saved arrangement — defaults */
  }
  return kit;
}

/** A room may sit anywhere inside the engine's limits as long as it doesn't overlap another. */
export function canPlace(label: string, x: number, y: number, w?: number, h?: number): boolean {
  if (!kit) return false;
  const room = kit.rooms.find((r) => r.label === label);
  if (!room || x < 0 || y < 0) return false;
  const rw = w ?? room.w;
  const rh = h ?? room.h;
  if (x + rw > MAX_TILES || y + rh + kit.top > MAX_TILES) return false;
  return kit.rooms.every((o) => o === room || x + rw <= o.x || o.x + o.w <= x || y + rh <= o.y || o.y + o.h <= y);
}

/** Sizes a room may take: from its designed size up to ROOM_MAX_GROW tiles larger. */
export function sizeRange(label: string): { minW: number; minH: number; maxW: number; maxH: number } | null {
  const d = designs.get(label);
  return d ? { minW: d.w, minH: d.h, maxW: d.w + ROOM_MAX_GROW, maxH: d.h + ROOM_MAX_GROW } : null;
}

/**
 * Rebuild a room at w×h from its design. Growing repeats the last inner column
 * (before the right wall) and the last inner row (above the bottom wall), so walls,
 * doors and floor carry on; furniture stays put, items on the right/bottom wall move
 * with it. Never smaller than designed — that's where the furniture and walkways fit.
 */
function applySize(room: RoomBlock, w: number, h: number): void {
  const d = designs.get(room.label);
  if (!d) return;
  w = Math.max(d.w, Math.min(d.w + ROOM_MAX_GROW, Math.round(w)));
  h = Math.max(d.h, Math.min(d.h + ROOM_MAX_GROW, Math.round(h)));
  const dw = w - d.w;
  const dh = h - d.h;
  const src = (i: number, n: number, grow: number) => (i < n - 1 ? i : i >= n - 1 + grow ? i - grow : n - 2);
  const tiles: number[] = [];
  const colors: RoomBlock['colors'] = [];
  for (let r = 0; r < h; r++) {
    for (let c = 0; c < w; c++) {
      const k = src(r, d.h, dh) * d.w + src(c, d.w, dw);
      tiles.push(d.tiles[k]);
      colors.push(d.colors[k]);
    }
  }
  room.w = w;
  room.h = h;
  room.tiles = tiles;
  room.colors = colors;
  room.furniture = d.furniture.map((f) => ({
    ...f,
    col: f.col >= d.w - 1 ? f.col + dw : f.col,
    row: f.row >= d.h - 1 ? f.row + dh : f.row,
  }));
}

/** Resize a room (if the new size fits where it stands), remember it, and say whether it changed. */
export function resizeRoom(label: string, w: number, h: number): boolean {
  const room = kit?.rooms.find((r) => r.label === label);
  const range = sizeRange(label);
  if (!kit || !room || !range) return false;
  w = Math.max(range.minW, Math.min(range.maxW, w));
  h = Math.max(range.minH, Math.min(range.maxH, h));
  if ((w === room.w && h === room.h) || !canPlace(label, room.x, room.y, w, h)) return false;
  applySize(room, w, h);
  try {
    localStorage.setItem(SIZE_KEY, JSON.stringify(Object.fromEntries(kit.rooms.map((r) => [r.label, { w: r.w, h: r.h }]))));
  } catch {
    /* not persisted — size lasts for this page */
  }
  return true;
}

/** Move a room (if it fits), remember the arrangement, and say whether it moved. */
export function moveRoom(label: string, x: number, y: number): boolean {
  const room = kit?.rooms.find((r) => r.label === label);
  if (!kit || !room || (room.x === x && room.y === y) || !canPlace(label, x, y)) return false;
  room.x = x;
  room.y = y;
  try {
    localStorage.setItem(POS_KEY, JSON.stringify(Object.fromEntries(kit.rooms.map((r) => [r.label, { x: r.x, y: r.y }]))));
  } catch {
    /* not persisted — arrangement lasts for this page */
  }
  return true;
}

/** Put the rooms on the hallway: the OfficeLayout the engine renders. */
export function compose(k: RoomKit): OfficeLayout {
  const cols = Math.max(...k.rooms.map((r) => r.x + r.w));
  const rows = Math.max(...k.rooms.map((r) => r.y + r.h)) + k.top;
  const n = cols * rows;
  const tiles = new Array<number>(n).fill(k.hallway.floor);
  const tileColors = new Array<Record<string, number> | null>(n).fill(k.hallway.color);
  const areaTiles = new Array<string | null>(n).fill(null);
  const furniture: OfficeLayout['furniture'] = [];
  k.rooms.forEach((room, i) => {
    for (let r = 0; r < room.h; r++) {
      for (let c = 0; c < room.w; c++) {
        const t = room.tiles[r * room.w + c];
        if (t === VOID) continue;
        const idx = (room.y + k.top + r) * cols + room.x + c;
        tiles[idx] = t;
        tileColors[idx] = room.colors[r * room.w + c];
        if (t !== WALL && t !== k.hallway.floor) areaTiles[idx] = room.label;
      }
    }
    // uids stay stable across moves, so agents keep their seats
    room.furniture.forEach((f, j) =>
      furniture.push({ uid: `r${i}-${j}`, type: f.type, col: room.x + f.col, row: room.y + k.top + f.row }),
    );
  });
  return {
    version: 1,
    cols,
    rows,
    tiles: tiles as OfficeLayout['tiles'],
    tileColors: tileColors as OfficeLayout['tileColors'],
    furniture,
    layoutRevision: 3,
    pets: k.pets,
    areas: k.rooms.map((r) => ({ label: r.label, color: r.color })),
    areaTiles,
  };
}

/** Block rectangle of a room in layout tiles (includes walls and the overhang row). */
export function roomRect(k: RoomKit, room: RoomBlock): { col: number; row: number; w: number; h: number } {
  return { col: room.x, row: room.y + k.top, w: room.w, h: room.h };
}
